CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS properties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title VARCHAR(220) NOT NULL, slug VARCHAR(240) UNIQUE NOT NULL, description TEXT NOT NULL, property_type VARCHAR(60) NOT NULL, listing_type VARCHAR(20) NOT NULL DEFAULT 'sale' CHECK(listing_type IN ('sale')), price NUMERIC(14,2) NOT NULL CHECK(price>0), city VARCHAR(100) NOT NULL, locality VARCHAR(120) NOT NULL, bedrooms INT NOT NULL DEFAULT 0, bathrooms INT NOT NULL DEFAULT 0, area_sqft INT NOT NULL DEFAULT 0, cover_image TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'available' CHECK(status IN ('available','under_offer','sold')), featured BOOLEAN NOT NULL DEFAULT FALSE, is_featured BOOLEAN NOT NULL DEFAULT FALSE, plot_area_sqft NUMERIC(12,2), price_per_sqft NUMERIC(12,2), facing VARCHAR(40), road_width_ft INT, approval_status VARCHAR(100), water_source VARCHAR(120), groundwater_depth_ft INT, water_availability_rating INT CHECK(water_availability_rating BETWEEN 1 AND 5), shopping_center_name VARCHAR(160), shopping_center_distance_km NUMERIC(8,2), vegetable_market_name VARCHAR(160), vegetable_market_distance_km NUMERIC(8,2), main_road_distance_km NUMERIC(8,2), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE properties ADD COLUMN IF NOT EXISTS is_featured BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE properties ADD COLUMN IF NOT EXISTS plot_area_sqft NUMERIC(12,2);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS price_per_sqft NUMERIC(12,2);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS facing VARCHAR(40);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS road_width_ft INT;
ALTER TABLE properties ADD COLUMN IF NOT EXISTS approval_status VARCHAR(100);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS water_source VARCHAR(120);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS groundwater_depth_ft INT;
ALTER TABLE properties ADD COLUMN IF NOT EXISTS water_availability_rating INT;
ALTER TABLE properties ADD COLUMN IF NOT EXISTS shopping_center_name VARCHAR(160);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS shopping_center_distance_km NUMERIC(8,2);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS vegetable_market_name VARCHAR(160);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS vegetable_market_distance_km NUMERIC(8,2);
ALTER TABLE properties ADD COLUMN IF NOT EXISTS main_road_distance_km NUMERIC(8,2);
CREATE INDEX IF NOT EXISTS properties_water_source_idx ON properties(water_source);
CREATE INDEX IF NOT EXISTS properties_approval_status_idx ON properties(approval_status);
CREATE INDEX IF NOT EXISTS properties_vegetable_market_distance_idx ON properties(vegetable_market_distance_km);
CREATE INDEX IF NOT EXISTS properties_city_idx ON properties(city);
CREATE INDEX IF NOT EXISTS properties_price_idx ON properties(price);
CREATE INDEX IF NOT EXISTS properties_status_idx ON properties(status);
CREATE TABLE IF NOT EXISTS bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE, booking_type VARCHAR(30) NOT NULL CHECK(booking_type IN ('purchase_enquiry','site_visit')), preferred_date DATE, message VARCHAR(1200), status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','contacted','confirmed','closed')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS bookings_user_idx ON bookings(user_id,created_at DESC);
